def table(frame):
    columns=list(frame.columns);rows=['| '+' | '.join(map(str,columns))+' |','|'+'|'.join(['---']*len(columns))+'|']
    def value(x):
        if isinstance(x,numbers.Real):return str(int(x)) if float(x).is_integer() else f'{x:.4f}'
        return str(x)
    for row in frame.itertuples(index=False,name=None):rows.append('| '+' | '.join(value(x) for x in row)+' |')
    return '\n'.join(rows)

